{"command":"cat << 'EOF' > test_embed.c
#define PY_SSIZE_T_CLEAN
#include <Python.h>

int main(int argc, char *argv[]) {
    Py_Initialize();
    PyRun_SimpleString("import sys; print('Hello from embedded Python:', sys.argv)");
    Py_Finalize();
    return 0;
}
EOF
gcc test_embed.c -o test_embed $(pkg-config --cflags --libs python3-embed)
./test_embed hello world
rm test_embed test_embed.c"}

